var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var page = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
var cate = (typeof MY_CATE !== 'undefined' && MY_CATE) ? MY_CATE : 'home';
var filterBy = '';
var filterArea = '';
var filterClass = '';

if (currentUrl.indexOf('#') !== -1) {
  var parts = currentUrl.split('#');
  if (parts[1]) {
    var rawCate = parts[1];
    if (rawCate.indexOf('?') !== -1) {
      var qParts = rawCate.split('?');
      cate = qParts[0];
      var qs = qParts[1];
      if (qs.indexOf('by=') !== -1) {
        var mBy = qs.match(/by=([^&]+)/);
        if (mBy) filterBy = mBy[1];
      }
      if (qs.indexOf('area=') !== -1) {
        var mArea = qs.match(/area=([^&]+)/);
        if (mArea) filterArea = decodeURIComponent(mArea[1]);
      }
      if (qs.indexOf('class=') !== -1) {
        var mClass = qs.match(/class=([^&]+)/);
        if (mClass) filterClass = decodeURIComponent(mClass[1]);
      }
    } else {
      cate = rawCate;
    }
  }
  if (parts[2]) {
    var pNum = parseInt(parts[2]);
    if (pNum) {
      page = pNum;
    }
  }
}

function cleanPic(pic) {
  if (!pic) return '';
  pic = pic.replace(/&amp;/g, '&').trim();
  if (pic.indexOf('img.php?url=') !== -1) {
    var m = pic.match(/url=([^&]+)/);
    if (m && m[1]) {
      pic = decodeURIComponent(m[1]);
      if (pic.indexOf('src=') !== -1) {
        var sm = pic.match(/src=([^&]+)/);
        if (sm && sm[1]) {
          pic = decodeURIComponent(sm[1]);
          if (pic.indexOf('http') !== 0) pic = 'https://' + pic;
        }
      }
    }
  }
  if (pic.indexOf('//') === 0) pic = 'https:' + pic;
  else if (pic.indexOf('/') === 0 && pic.indexOf('/static') === -1) pic = 'https://www.jcy23.com' + pic;
  if (pic && pic.indexOf('@Referer=') === -1) {
    pic += '@Referer=https://www.jcy23.com/';
  }
  return pic;
}

var d = [];



// ==================== 1. 首页模式 (大屏轮播 + 热门海报模块) ====================
if (cate === 'home' && page === 1 && !filterBy && !filterArea && !filterClass) {
  var homeHtml = request('https://www.jcy23.com/', {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Referer': 'https://www.jcy23.com/'
    }
  });

  // (1) 21:9 沉浸大屏轮播 (Banner Carousel)
  var slides = [];
  var swiperSlides = pdfa(homeHtml, '.swiper-slide');
  for (var s = 0; s < swiperSlides.length; s++) {
    var sSlide = swiperSlides[s];
    var bStyle = pdfh(sSlide, 'a.banner&&style') || '';
    if (bStyle) {
      var mBg = bStyle.match(/url\(([^)]+)\)/);
      var bHref = pd(sSlide, 'a.banner&&href', 'https://www.jcy23.com');
      var sTitle = pdfh(sSlide, '.v-title span&&Text') || pdfh(sSlide, '.title a&&Text') || '精彩热播';
      var sDesc = pdfh(sSlide, '.v-ins p&&Text') || pdfh(sSlide, '.ins p&&Text') || '沉浸画质 · 点击直达';
      if (mBg && bHref) {
        var bgUrl = mBg[1].replace(/['"]/g, '');
        slides.push({
          title: sTitle,
          desc: sDesc,
          img: cleanPic(bgUrl),
          url: bHref
        });
      }
    }
  }

  if (slides.length > 0) {
    d.push({
      title: slides[0].title,
      desc: slides[0].desc,
      pic_url: slides[0].img,
      url: slides[0].url,
      col_type: 'banner_carousel',
      extra: {
        slides: slides
      }
    });
  }

  // (2) 热门精选模块 (海报卡片流，严格过滤无卡片空悬标题)
  var modules = pdfa(homeHtml, '.module');
  for (var mIdx = 0; mIdx < modules.length; mIdx++) {
    var mod = modules[mIdx];
    var mTitle = pdfh(mod, '.module-title&&Text') || pdfh(mod, '.module-heading h2&&Text') || pdfh(mod, 'h2&&Text');
    if (!mTitle) continue;

    var mCards = pdfa(mod, '.module-poster-item');
    if (mCards && mCards.length > 0) {
      var modItems = [];
      for (var cIdx = 0; cIdx < Math.min(mCards.length, 9); cIdx++) {
        var card = mCards[cIdx];
        var cTitle = pdfh(card, '.module-poster-item-title&&Text') || pdfh(card, 'img&&alt') || pdfh(card, 'a&&title') || pdfh(card, '&&title');
        var cLink = pd(card, 'a&&href', 'https://www.jcy23.com') || pd(card, '&&href', 'https://www.jcy23.com');
        var cPic = pdfh(card, 'img&&data-original') || pdfh(card, 'img&&src');
        var cNote = pdfh(card, '.module-item-note&&Text') || pdfh(card, '.module-item-text&&Text');
        if (cTitle && cLink) {
          modItems.push({
            title: cTitle,
            desc: cNote,
            pic_url: cleanPic(cPic),
            url: cLink,
            col_type: 'movie_3'
          });
        }
      }
      if (modItems.length > 0) {
        d.push({
          title: '🔥 ' + mTitle,
          col_type: 'text_1'
        });
        for (var k = 0; k < modItems.length; k++) {
          d.push(modItems[k]);
        }
      }
    }
  }

  setResult(d);
} else {
  // ==================== 2. 分类与排行榜专区模式 ====================
  var targetUrl = '';
  var isSearchType = false;

  if (cate === 'ranking' || cate === 'hot') {
    targetUrl = 'https://www.jcy23.com/index.php/label/hot.html';
  } else if (cate === 'riman') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/show/area/' + encodeURIComponent('日本') + '/id/1/page/' + page + '.html';
  } else if (cate === 'guoman') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/show/area/' + encodeURIComponent('大陆') + '/id/1/page/' + page + '.html';
  } else if (cate === 'juchang') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/show/id/2/page/' + page + '.html';
  } else if (cate === 'meiman') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/show/area/' + encodeURIComponent('美国') + '/id/1/page/' + page + '.html';
  } else if (cate === 'teshe') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/search/page/' + page + '/wd/' + encodeURIComponent('特摄') + '.html';
    isSearchType = true;
  } else if (cate === 'shaoer') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/search/page/' + page + '/wd/' + encodeURIComponent('少儿') + '.html';
    isSearchType = true;
  } else if (cate === 'dongtaiman') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/search/page/' + page + '/wd/' + encodeURIComponent('动态漫画') + '.html';
    isSearchType = true;
  } else if (cate === 'guess') {
    targetUrl = 'https://www.jcy23.com/index.php/vod/show/by/score/id/1/page/' + page + '.html';
  } else {
    var realCate = (cate === 'home' ? '1' : cate);
    targetUrl = 'https://www.jcy23.com/index.php/vod/show/';
    if (filterBy) targetUrl += 'by/' + filterBy + '/';
    if (filterArea) targetUrl += 'area/' + encodeURIComponent(filterArea) + '/';
    if (filterClass) targetUrl += 'class/' + encodeURIComponent(filterClass) + '/';
    targetUrl += 'id/' + realCate + '/page/' + page + '.html';
  }

  var catHtml = request(targetUrl, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Referer': 'https://www.jcy23.com/'
    }
  });

  if (cate === 'ranking' || cate === 'hot') {
    d.push({
      title: '🔥 全站热门风向标 · 每日实时榜单',
      col_type: 'text_1'
    });
  }

  var items = [];
  if (isSearchType || cate === 'ranking' || cate === 'hot') {
    items = pdfa(catHtml, '.module-card-item');
    if (!items || items.length === 0) {
      items = pdfa(catHtml, '.module-item');
    }
  } else {
    items = pdfa(catHtml, '.module-poster-item');
    if (!items || items.length === 0) {
      items = pdfa(catHtml, '.module-item');
    }
  }

  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    var title = pdfh(it, '.module-card-item-title&&Text') || pdfh(it, '.module-poster-item-title&&Text') || pdfh(it, 'img&&alt') || pdfh(it, 'a&&title') || pdfh(it, '&&title');
    var link = pd(it, '.module-card-item-poster&&href', 'https://www.jcy23.com') || pd(it, 'a&&href', 'https://www.jcy23.com') || pd(it, '&&href', 'https://www.jcy23.com');
    var pic = pdfh(it, 'img&&data-original') || pdfh(it, 'img&&src');
    var note = pdfh(it, '.module-item-note&&Text') || pdfh(it, '.module-item-text&&Text') || pdfh(it, '.module-card-item-info&&Text');
    if (title && link) {
      d.push({
        title: title.trim(),
        url: link,
        pic_url: cleanPic(pic),
        desc: (note ? note.trim() : ''),
        col_type: 'movie_3'
      });
    }
  }

  setResult(d);
}

