js:
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var html = '';
if (typeof currentUrl === 'string' && currentUrl.indexOf('http') === 0) {
  html = request(currentUrl, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Referer': 'https://www.jcy23.com/'
    }
  });
} else if (typeof input === 'string') {
  html = input;
}

function cleanPic(pic) {
  if (!pic) return '';
  pic = pic.replace(/&amp;/g, '&').trim();
  if (pic.indexOf('img.php?url=') !== -1) {
    var m = pic.match(/url=([^&]+)/);
    if (m && m[1]) {
      pic = decodeURIComponent(m[1]);
      if (pic.indexOf('src=') !== -1) {
        var sm = pic.match(/src=([^&]+)/);
        if (sm && sm[1]) {
          pic = decodeURIComponent(sm[1]);
          if (pic.indexOf('http') !== 0) pic = 'https://' + pic;
        }
      }
    }
  }
  if (pic.indexOf('//') === 0) pic = 'https:' + pic;
  else if (pic.indexOf('/') === 0 && pic.indexOf('/static') === -1) pic = 'https://www.jcy23.com' + pic;
  if (pic && pic.indexOf('@Referer=') === -1) {
    pic += '@Referer=https://www.jcy23.com/';
  }
  return pic;
}

var cleanTitle = pdfh(html, 'h1&&Text') || pdfh(html, '.module-info-heading h1&&Text') || '动漫共和国';
var pic = pd(html, '.module-item-pic img&&data-original', currentUrl) || pd(html, '.module-item-pic img&&src', currentUrl);
var desc = pdfh(html, '.module-info-introduction-content&&Text') || pdfh(html, '.module-info-item-content&&Text') || '';

var d = [];
d.push({
  title: '剧名：' + cleanTitle,
  desc: (desc.length > 120 ? desc.substring(0, 120) + '...' : desc),
  pic_url: cleanPic(pic),
  url: currentUrl,
  col_type: 'pic_1_card'
});

var tabs = pdfa(html, '.module-tab-items-box .module-tab-item');
var playLists = pdfa(html, '.module-play-list-content');

var blocked = ['TX', 'YK', 'BL', '优酷', '腾讯', '爱奇艺', 'B站'];
var validLines = [];

for (var t = 0; t < playLists.length; t++) {
  var rawName = '线路' + (t + 1);
  if (tabs && tabs[t]) {
    var rawText = pdfh(tabs[t], 'span&&Text') || pdfh(tabs[t], '&&Text');
    if (rawText) rawName = rawText;
  }
  var epLinks = pdfa(playLists[t], '.module-play-list-link');
  if (!epLinks || epLinks.length === 0) continue;

  var uName = rawName.toUpperCase();
  var isBlocked = false;
  for (var b = 0; b < blocked.length; b++) {
    if (uName.indexOf(blocked[b].toUpperCase()) !== -1) {
      isBlocked = true;
      break;
    }
  }
  if (isBlocked) continue;

  var displayName = rawName;
  var priority = 10;
  if (rawName.indexOf('稳定') !== -1) {
    displayName = '🎬 稳定原画线 (1080P超清·推荐)';
    priority = 100;
  } else if (rawName.indexOf('4K') !== -1) {
    displayName = '✨ ' + rawName + ' (超高清专线)';
    priority = 90;
  } else if (rawName.indexOf('优质') !== -1) {
    displayName = '⚡ 优质极速线 (低延迟秒播)';
    priority = 80;
  } else if (rawName.indexOf('备用') !== -1) {
    displayName = '🛡️ 备用专线 (防卡顿)';
    priority = 60;
  } else {
    displayName = '📺 ' + rawName;
    priority = 50;
  }

  validLines.push({
    title: displayName,
    priority: priority,
    epLinks: epLinks
  });
}

// 稳定原画超清线置顶排序，首选最高画质
validLines.sort(function(a, b) {
  return b.priority - a.priority;
});

// 若全被过滤则保底首个
if (validLines.length === 0 && playLists.length > 0) {
  validLines.push({
    title: '🎬 播放专线',
    epLinks: pdfa(playLists[0], '.module-play-list-link')
  });
}

var lazyCode = '@lazyRule=.js:(() => {\n  var pageUrl = input;\n  var playHtml = request(pageUrl, {\n    headers: {\n      "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",\n      "Referer": "https://www.jcy23.com/"\n    }\n  });\n  var playUrl = "";\n  var mPlayer = playHtml.match(/player_aaaa\\s*=\\s*\\{([\\s\\S]*?)\\}<\\s*\\/script>/);\n  if (mPlayer && mPlayer[1]) {\n    var m = mPlayer[1].match(/"url"\\s*:\\s*"([^"]+)"/);\n    if (m && m[1]) {\n      playUrl = m[1].replace(/\\\\/g, "");\n    }\n  }\n  if (playUrl && playUrl.indexOf("http") === 0) {\n    return playUrl;\n  }\n  return pageUrl;\n})()';

for (var vl = 0; vl < validLines.length; vl++) {
  var lineItem = validLines[vl];
  d.push({
    title: lineItem.title,
    col_type: 'text_1'
  });
  for (var e = 0; e < lineItem.epLinks.length; e++) {
    var ep = lineItem.epLinks[e];
    var epTitle = pdfh(ep, 'span&&Text') || pdfh(ep, 'a&&title') || ('第' + (e + 1) + '集');
    var epHref = pd(ep, 'a&&href', 'https://www.jcy23.com');
    d.push({
      title: epTitle,
      url: epHref + lazyCode,
      col_type: 'text_3'
    });
  }
}

setResult(d);
